# POST /api/sheets/{sheetId}/people/{personId}/merge — merge a person into another on the sheet, by a steward. The merged
# person's claims move to the other (numbers and dates kept, listed after the other's in the order they were added, each
# losing any figure a statement bound); their name and aliases become the other's aliases; their patrons are added to the
# other's (not the other themselves, no repeats), anyone naming them as patron names the other instead (no repeats), and
# their pool memberships move to the other (shares added where the other is already a member). Their statements, holds,
# watchers and contact are dropped, and they leave the sheet. A body without the person merged into is a 400, a person not
# on the sheet a 404; a user other than a steward, a merge into the same person or one not on the sheet, or either of them
# retired, is a 400 — none writes anything. Responds with the person merged into, as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckMerge
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonMerged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithMerge
# POST /api/sheets/{sheetId}/people/{personId}/retire — retire a person from a date (blank: the sheet's today). A date
# that is not yyyy-MM-dd is a 400 and a person not on the sheet a 404, neither writing anything. The person counts as
# retired at once, whatever the date; no claim of theirs may then be dated after it. From the day the retirement date is
# reached (the sheet's today on or after it), their OPEN and PENDING claims not bound by a statement leave every live
# total, and the figures that moves are written. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonRetired
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: a merge names the person merged into and the signed-in user. */
public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeRequest> body) throws InvalidPersonException {
        if (request == null || request.intoId() == null) {
            throw new InvalidPersonException("A merge needs the person merged into");
        }
        String by = request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidPersonException("The user merging is required");
        }
        body.set(new MergeRequest(request.intoId(), by));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Checks a merge: only a steward merges, and only into another person on the sheet; a merge into the same person, or
 *  with either of them retired (whatever the date), is refused. */
public class CheckMerge {
    public void check(@Val Person person, @Val MergeRequest request, PersonRepository people, RoleRepository roles,
            Out<PersonMerge> merge) throws InvalidPersonException {
        if (!RoleRepository.STEWARD.equals(roles.roleOf(person.sheetId(), request.by()))) {
            throw new InvalidPersonException("Only a steward merges people");
        }
        Person into = people.find(person.sheetId(), request.intoId());
        if (into == null || into.id() == person.id()) {
            throw new InvalidPersonException("A person merges into another person on the sheet");
        }
        if (person.retired() || into.retired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        merge.set(new PersonMerge(person, into, request.by()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Stores the merge (see PersonMerger#merge). */
public class MergePerson {
    public void merge(@Val PersonMerge merge, PersonMerger merger) {
        merger.merge(merge.from().sheetId(), merge.from(), merge.into());
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Stores a merge of one person into another on the sheet (see #merge). */
@Repository
public class PersonMerger {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PersonMerger(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /**
     * Merges {@code from} into {@code into}: from's claims move to into (numbers and dates kept, listed after every claim
     * on the sheet in the order they were added, each unbound from any statement figure); from's name and aliases become
     * into's aliases; from's patrons are added to into's (not into themselves, no repeats) and anyone naming from as
     * patron names into instead (no repeats; into never their own patron); from's pool memberships move to into (shares
     * added where into is already a member). From's statements, holds, watchers, contact and grades are dropped, and from
     * leaves the sheet (kept, as they stood, only for reading the sheet as of a date before the merge).
     */
    public void merge(String sheetId, Person from, Person into) {
        long f = from.id();
        long t = into.id();
        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
                Long.class, sheetId, f);
        for (Long id : claims) {
            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, "
                    + "listed = (SELECT COALESCE(MAX(c.listed), 0) + 1 FROM claim c WHERE c.sheet_id = ?) WHERE id = ?",
                    t, sheetId, id);
        }

        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", t, sheetId, f);

        for (Map<String, Object> p : jdbc.queryForList("SELECT patron_id, added_on FROM patron WHERE sheet_id = ? AND person_id = ?",
                sheetId, f)) {
            addPatron(sheetId, t, ((Number) p.get("patron_id")).longValue(), p.get("added_on"));
        }
        for (Map<String, Object> p : jdbc.queryForList("SELECT person_id, added_on FROM patron WHERE sheet_id = ? AND patron_id = ?",
                sheetId, f)) {
            addPatron(sheetId, ((Number) p.get("person_id")).longValue(), t, p.get("added_on"));
        }
        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, f, f);

        for (Map<String, Object> m : jdbc.queryForList("SELECT id, pool_id, share FROM pool_member WHERE person_id = ? ORDER BY id", f)) {
            long poolId = ((Number) m.get("pool_id")).longValue();
            BigDecimal share = (BigDecimal) m.get("share");
            List<Long> theirs = jdbc.queryForList("SELECT id FROM pool_member WHERE pool_id = ? AND person_id = ?", Long.class,
                    poolId, t);
            if (theirs.isEmpty()) {
                jdbc.update("UPDATE pool_member SET person_id = ? WHERE id = ?", t, m.get("id"));
            } else {
                jdbc.update("UPDATE pool_member SET share = share + ? WHERE id = ?", share, theirs.get(0));
                jdbc.update("DELETE FROM pool_member WHERE id = ?", m.get("id"));
            }
        }

        StringBuilder grades = new StringBuilder();
        for (PersonGrade g : from.grades()) {
            grades.append(grades.length() == 0 ? "" : ";").append(g.grade()).append('@').append(g.from() == null ? "" : g.from());
        }
        jdbc.update("INSERT INTO person_merged (id, sheet_id, name, grades, retired_from, terms, contact, added_on, merged_on)"
                + " SELECT id, sheet_id, name, ?, retired_from, terms, contact, added_on, ? FROM person WHERE sheet_id = ? AND id = ?",
                grades.toString(), java.sql.Date.valueOf(sheets.today(sheetId)), sheetId, f);

        for (String table : List.of("statement", "person_hold", "watch", "person_grade", "person_grade_log",
                "person_retire_log", "person_terms_log")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, f);
        }
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, f);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_on) VALUES (?, ?, ?, ?)", sheetId, t, from.name(),
                java.sql.Date.valueOf(sheets.today(sheetId)));
    }

    /** Names the patron for the person, unless it is themselves or they already have them. */
    private void addPatron(String sheetId, long personId, long patronId, Object addedOn) {
        if (personId == patronId) {
            return;
        }
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM patron WHERE sheet_id = ? AND person_id = ? AND patron_id = ?",
                Integer.class, sheetId, personId, patronId);
        if (n != null && n == 0) {
            jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id, added_on) VALUES (?, ?, ?, ?)", sheetId, personId,
                    patronId, addedOn);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_MERGED from=<merged name> into=<name> to the audit file once the merge is stored, then the figures the
 *  merge moved (see Rollup). */
public class RecordPersonMerged {
    public void record(@Val PersonMerge merge, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String sheetId = merge.from().sheetId();
        audit.record("PERSON_MERGED sheet=" + sheetId + " by=" + merge.by() + " from=" + merge.from().name() + " into="
                + merge.into().name());
        rollup.record(sheetId, merge.by(), before);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as stored now. */
public class RespondWithMerge {
    public void respond(@Val PersonMerge merge, PersonRepository people, ObjectResponse<Person> response) {
        response.send(people.find(merge.into().sheetId(), merge.into().id()));
    }
}
package net.officefloor.hq.app.person;

/** Body of merging a person into another: the id of the person they merge into, and who merges them. */
public record MergeRequest(Long intoId, String by) {
}

