  test("transfer person scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
    expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "99.95", "note": ""})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-01"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "ben@x"}));
    expect(await ui.addAlias(pg_uma, p_ben, "Al")).toBe(true);
    expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
    expect(await ui.ratePreview(pg_uma, "C", "20.00")).toEqual({ count: 0, diff: "0.00" });
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C", "gradeFrom": "2026-02-25"})).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "ref": "inv 7"}));
    expect(await ui.addProof(pg_uma, c_ben_0)).toBe(true);
    await ui.refresh(pg_uma);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.ratePreview(pg_wes, "A", "10.00")).toEqual({ count: 0, diff: "0.00" });
    expect(await ui.editPerson(pg_wes, p_cam, {"grade": "C"})).toBe(true);
    expect(await ui.editInline(pg_wes, c_ben_0, "10.25")).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ben, {"grade": "A", "gradeFrom": "2026-03-20"})).toBe(true);
    expect(await ui.statement(pg_wes, p_ben)).toBe(true);
    expect(await ui.editPerson(pg_wes, p_cam, {"grade": "B", "gradeFrom": "2026-03-20"})).toBe(true);
    await ui.refresh(pg_wes);
    expect(await ui.statement(pg_wes, p_ada)).toBe(true);
    expect(await ui.claimAction(pg_wes, c_ben_0, "open")).toBe(false);
    const c_ada_0 = ui.must(await ui.claimFromTemplate(pg_wes, p_ada, "T1"));
    await ui.refresh(pg_uma);
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.periodAction(pg_vic, "P1", "reopen")).toBe(true);
    await ui.setAsOf(pg_vic, "2026-03-15");
    await ui.refresh(pg_vic);
import { useCallback, useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheetDueTotal, useSheetOverdue } from '../header/totals';
import { usePeople } from '../people/people';
import { sum } from '../rates/rates';

/** The ids of the sheet's descendants: the sheets naming it as their parent, then theirs, and so on. */
function useDescendants(sheetId: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants'],
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/descendants`),
  });
}

/** One sheet's own figures, as its header shows them. */
type Figures = { people: number; due: string; overdue: string };

/** Works out one sheet's figures with the same hooks as its header, and reports them. Shows nothing. */
function SheetFigures({ sheetId, report }: { sheetId: string; report: (sheetId: string, f: Figures) => void }) {
  const people = (usePeople(sheetId).data ?? []).length;
  const due = useSheetDueTotal(sheetId);
  const overdue = useSheetOverdue(sheetId).total;
  useEffect(() => report(sheetId, { people, due, overdue }), [report, sheetId, people, due, overdue]);
  return null;
}

/** The consolidated figures over the sheet and all its descendants: their people counted, and each sheet's
 *  due-total and overdue-total (as that sheet shows it) added up. A sheet with no children shows its own. */
function Consolidated({ sheetId }: { sheetId: string }) {
  const descendants = useDescendants(sheetId);
  const sheets = [sheetId, ...(descendants.data ?? [])];
  const [figures, setFigures] = useState<Record<string, Figures>>({});
  const report = useCallback(
    (id: string, f: Figures) => setFigures((all) => ({ ...all, [id]: f })),
    [],
  );
  const counted = sheets.map((id) => figures[id]).filter((f): f is Figures => f !== undefined);

  return (
    <section data-testid="consolidated">
      {sheets.map((id) => (
        <SheetFigures key={id} sheetId={id} report={report} />
      ))}
      Consolidated: people <span data-testid="consolidated-people-count">{counted.reduce((n, f) => n + f.people, 0)}</span>
      {' · '}Due total <span data-testid="consolidated-due-total">{sum(counted.map((f) => f.due))}</span>
      {' · '}Overdue total <span data-testid="consolidated-overdue-total">{sum(counted.map((f) => f.overdue))}</span>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: -9, Component: Consolidated });

